// Narrator track (reference has a voiceover reading along with the on-screen text). Clips: Gemini TTS, generated by
// scripts/voiceover.py; measured lengths in public/audio/vo/vo.json. Each line starts relative to its shot (SHOTS + offset)
// so it lands with the matching on-screen words. The BGM ducks under every line (see duckAt).
import React from 'react';
import { Audio, Sequence, staticFile } from 'remotion';
import { SHOTS, beatF, DROP_BEAT, FPS } from './timeline';
import vo from '../public/audio/vo/vo.json';

const S = SHOTS;
const len = (id: string) => Math.ceil(((vo as Record<string, { seconds: number }>)[id]?.seconds ?? 0) * FPS);
const v03 = len('v03');

export const VO: { id: string; at: number }[] = [
  { id: 'v01', at: S.hook.from + 12 }, // pills roll: booking / regular / $140
  { id: 'v02', at: S.type.from + 18 }, // "Who answers when you're … with a customer?"
  { id: 'v03', at: beatF(DROP_BEAT) - Math.round(v03 * 0.62) }, // "Meet Pulse" — "Pulse" lands on the drop
  { id: 'v04', at: S.reveal.from + 176 }, // tagline appears
  { id: 'v05', at: S.today.from + 26 }, // "Every call, answered."
  { id: 'v06', at: S.today.from + 120 }, // "Written straight into your day."
  { id: 'v07', at: S.converge.from + 6 },
  { id: 'v08', at: S.urgent.from + 6 },
  { id: 'v09', at: S.history.from + 6 },
  { id: 'v10', at: S.history.from + 98 }, // "Names spelled back…"
  { id: 'v11', at: S.funnel.from + 2 },
  { id: 'v12', at: S.voicemail.from + 8 },
  { id: 'v13', at: S.outro.from + 12 },
  { id: 'v14', at: S.outro.from + 116 }, // CTA
];

// BGM gain multiplier: 1 normally, ~0.4 under speech, 6f ramps either side.
export const duckAt = (f: number) => {
  let g = 1;
  for (const c of VO) {
    const a = c.at, b = c.at + len(c.id);
    const k = f < a - 6 || f > b + 8 ? 0 : f < a ? (f - (a - 6)) / 6 : f > b ? 1 - (f - b) / 8 : 1;
    g = Math.min(g, 1 - 0.6 * k);
  }
  return g;
};

export const Voiceover: React.FC = () => (
  <>
    {VO.map((c) => (
      <Sequence key={c.id} from={c.at} durationInFrames={len(c.id) + 4} name={`vo: ${c.id}`}>
        <Audio src={staticFile(`audio/vo/${c.id}.wav`)} volume={1} />
      </Sequence>
    ))}
  </>
);
